SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state", "n_short", "n_price", "n_due", 'release' AS "route", 'all checks passed' AS "verdict_reason"
FROM (SELECT "t26"."order_number", "t26"."customer", "t26"."channel", "t26"."fulfilling_warehouse", "t26"."value", "t26"."placed_date", "t26"."state", COALESCE("t26"."n_short", 0) AS "n_short", COALESCE("t26"."n_price", 0) AS "n_price", COALESCE("t32"."n_due", 0) AS "n_due"
        FROM (SELECT "t14"."order_number", "t14"."customer", "t14"."channel", "t14"."fulfilling_warehouse", "t14"."value", "t14"."placed_date", "t14"."state", "t14"."n_short", "t25"."n_price"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "t13"."n_short"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                FROM (SELECT "t8"."order_number", "t8"."customer", "t8"."channel", "t8"."fulfilling_warehouse", "t8"."value", "t8"."placed_date", "t8"."state", "t8"."line_no", "t8"."item", "t8"."quantity", "t8"."unit_price", "t8"."ext_sales_price", "t8"."warehouse", "t8"."sold_date", "t8"."customer0", "t8"."channel0", "t8"."as_of_date", "t8"."quantity_on_hand", "t8"."_ttrp_g_n8_0", "t8"."_ttrp_g_n8_1", "t9"."warehouse" AS "warehouse0", "t9"."from_date", "t9"."to_date", "t9"."reason", COALESCE("t8"."quantity_on_hand", 0) AS "on_hand", "t9"."warehouse" IS NOT NULL AS "outage"
                                        FROM (SELECT "t3"."order_number", "t3"."customer", "t3"."channel", "t3"."fulfilling_warehouse", "t3"."value", "t3"."placed_date", "t3"."state", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."ext_sales_price", "t3"."warehouse", "t3"."sold_date", "t3"."customer0", "t3"."channel0", "t7"."as_of_date", "t7"."quantity_on_hand", "t7"."_ttrp_g_n8_0", "t7"."_ttrp_g_n8_1"
                                                FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t2"
                                                            INNER JOIN "sales_line" ON "t2"."order_number" = "sales_line"."order_number") AS "t3"
                                                    LEFT JOIN (SELECT "t4"."as_of_date", "t4"."item", "t4"."warehouse", "t4"."quantity_on_hand", "t4"."_ttrp_g_n8_0", "t4"."_ttrp_g_n8_1"
                                                        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1"
                                                                FROM "inventory") AS "t4"
                                                            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                FROM "inventory"
                                                                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t6" ON "t4"."_ttrp_g_n8_0" = "t6"."_ttrp_g_n8_0" AND "t4"."_ttrp_g_n8_1" = "t6"."_ttrp_g_n8_1" AND "t4"."as_of_date" = "t6"."_ttrp_latest_n8") AS "t7" ON "t3"."item" = "t7"."item" AND "t3"."warehouse" = "t7"."warehouse") AS "t8"
                                            LEFT JOIN (SELECT *
                                                FROM "warehouse_outage"
                                                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t9" ON "t8"."warehouse" = "t9"."warehouse") AS "t10"
                                WHERE "t10"."outage" OR "t10"."on_hand" < "t10"."quantity"
                                GROUP BY "order_number") AS "t13" ON "t0"."order_number" = "t13"."order_number") AS "t14"
                    LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                        FROM (SELECT "t17"."order_number", "t17"."line_no", "t17"."item", "t17"."unit_price", "t17"."customer", "t17"."channel", "t17"."placed_date", "t21"."order_number" AS "order_number0", "t21"."line_no" AS "line_no0", "t21"."price"
                                FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t16"."customer", "t16"."channel", "t16"."placed_date"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t16"
                                            INNER JOIN "sales_line" AS "sales_line0" ON "t16"."order_number" = "sales_line0"."order_number") AS "t17"
                                    INNER JOIN (SELECT "t20"."order_number", "t20"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                        FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t19"."customer", "t19"."channel", "t19"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t19"
                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t19"."order_number" = "sales_line1"."order_number") AS "t20"
                                            LEFT JOIN "customer_price" ON "t20"."item" = "customer_price"."item" AND "t20"."customer" = "customer_price"."customer" AND "t20"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t20"."placed_date" <= "customer_price"."valid_to")
                                            LEFT JOIN "price_list" ON "t20"."item" = "price_list"."item" AND "t20"."channel" = "price_list"."channel" AND "t20"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t20"."placed_date" <= "price_list"."valid_to")) AS "t21" ON "t17"."order_number" = "t21"."order_number" AND "t17"."line_no" = "t21"."line_no") AS "t22"
                        WHERE "t22"."price" IS NULL OR ABS("t22"."unit_price" - "t22"."price") > :tolerance
                        GROUP BY "order_number0") AS "t25" ON "t14"."order_number" = "t25"."order_number") AS "t26"
            LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                FROM (SELECT "t28"."order_number", "t28"."customer", "t28"."channel", "t28"."fulfilling_warehouse", "t28"."value", "t28"."placed_date", "t28"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t28"
                            INNER JOIN "invoice" ON "t28"."customer" = "invoice"."customer") AS "t29"
                WHERE "t29"."status" = 'open' AND "t29"."due" < :as_of
                GROUP BY "order_number") AS "t32" ON "t26"."order_number" = "t32"."order_number") AS "t33"
WHERE "t33"."n_short" = 0 AND "t33"."n_price" = 0 AND "t33"."n_due" = 0 AND "t33"."value" <= :confirmation_threshold
